# multisoul-hermes-plugin-marker
# Auto-generated by Norma OS. Forwards Hermes Agent lifecycle events to the local Norma app.
# Fail open: Hermes must never block or slow down because Norma OS is unavailable.
import json
import os
import threading
import urllib.request

_TIMEOUT_SECONDS = 2
# One char over Norma's 1200 cap so the receiver can flag truncation.
_RESPONSE_LIMIT = 1201
_last_tool = {}
_last_response = {}
_lock = threading.Lock()


def _post(name, payload):
    endpoint = os.environ.get("MULTISOUL_HOOK_ENDPOINT")
    token = os.environ.get("MULTISOUL_HOOK_TOKEN")
    node = os.environ.get("MULTISOUL_NODE_ID")
    if not (endpoint and token and node):
        return
    body = dict(payload)
    body["hook_event_name"] = name
    try:
        request = urllib.request.Request(
            endpoint,
            json.dumps(body).encode("utf-8"),
            {"Authorization": "Bearer " + token, "Content-Type": "application/json"},
        )
        urllib.request.urlopen(request, timeout=_TIMEOUT_SECONDS).read()
    except Exception:
        pass


def _send(name, payload, wait=False):
    worker = threading.Thread(target=_post, args=(name, payload), daemon=True)
    worker.start()
    if wait:
        worker.join(1)


def _base(kwargs):
    payload = {}
    session_id = kwargs.get("session_id")
    if isinstance(session_id, str) and session_id:
        payload["session_id"] = session_id
    return payload


def _session_key(kwargs):
    return kwargs.get("session_id") or ""


def _on_session_start(**kwargs):
    _send("SessionStart", _base(kwargs))


def _on_pre_llm_call(**kwargs):
    _send("UserPromptSubmit", _base(kwargs))


def _on_pre_tool_call(**kwargs):
    payload = _base(kwargs)
    tool = kwargs.get("tool_name")
    if isinstance(tool, str) and tool:
        payload["tool_name"] = tool
        with _lock:
            _last_tool[_session_key(kwargs)] = tool
    _send("PreToolUse", payload)


def _on_post_tool_call(**kwargs):
    payload = _base(kwargs)
    tool = kwargs.get("tool_name")
    if isinstance(tool, str) and tool:
        payload["tool_name"] = tool
    _send("PostToolUse", payload)


def _on_human_input_request(**kwargs):
    if kwargs.get("kind") != "approval":
        return
    payload = _base(kwargs)
    with _lock:
        tool = _last_tool.get(_session_key(kwargs))
    if tool:
        payload["tool_name"] = tool
    _send("PermissionRequest", payload)


def _on_human_input_resolved(**kwargs):
    _send("PostToolUse", _base(kwargs))


def _on_api_request_error(**kwargs):
    if kwargs.get("retryable") is not False:
        return
    payload = _base(kwargs)
    reason = kwargs.get("reason")
    payload["message"] = reason if isinstance(reason, str) and reason else "api_request_error"
    _send("StopFailure", payload)


def _on_post_llm_call(**kwargs):
    text = kwargs.get("assistant_response")
    if isinstance(text, str) and text:
        with _lock:
            _last_response[_session_key(kwargs)] = text[:_RESPONSE_LIMIT]


def _on_session_end(**kwargs):
    payload = _base(kwargs)
    with _lock:
        text = _last_response.pop(_session_key(kwargs), None)
    if text:
        payload["last_assistant_message"] = text
    if kwargs.get("interrupted") is True:
        payload["interrupted"] = True
    _send("Stop", payload)


def _on_session_finalize(**kwargs):
    _send("SessionEnd", _base(kwargs), wait=True)


def register(ctx):
    _send("SessionStart", {})
    for hermes_event, callback in (
        ("on_session_start", _on_session_start),
        ("pre_llm_call", _on_pre_llm_call),
        ("pre_tool_call", _on_pre_tool_call),
        ("post_tool_call", _on_post_tool_call),
        ("on_human_input_request", _on_human_input_request),
        ("on_human_input_resolved", _on_human_input_resolved),
        ("api_request_error", _on_api_request_error),
        ("post_llm_call", _on_post_llm_call),
        ("on_session_end", _on_session_end),
        ("on_session_finalize", _on_session_finalize),
    ):
        ctx.register_hook(hermes_event, callback)
